parameters.jsCode:
const raw = $input.first().json.candidates[0].content.parts[0].text;
const d = JSON.parse(raw);
const form = $('On form submission').first().json;

const hex = /^#[0-9A-Fa-f]{6}$/;
const color = (c, fallback) => (hex.test(c) ? c : fallback);
const ds = d.design_system || {};

const slides = [
  ...d.content_slides.map(s => ({
    heading: s.heading,
    body: s.body,
    visual: s.visual_direction || ''
  })),
  { heading: d.cta_slide.heading, body: d.cta_slide.body, visual: '' }
];

return [{
  json: {
    platform: form['Platform'],
    coverTitle: d.cover_title,
    slides,
    caption: d.caption,
    hashtags: (d.hashtags || []).map(h => '#' + h.replace(/^#/, '')).join(' '),
    headlineOptions: d.headline_options || [],
    theme: {
      name: ds.theme_name || 'Theme',
      background: color(ds.background_color, '#FFFFFF'),
      text: color(ds.text_color, '#222222'),
      accent: color(ds.accent_color, '#0B6EFD'),
      headingFont: ds.heading_font || 'Poppins',
      bodyFont: ds.body_font || 'Lato'
    }
  }
}];

const deck = $input.first().json;
const presentationId = $('Create Deck').first().json.id;
const d = $('Parse').first().json;
const brand = String($('On form submission').first().json['Brand Line'] || '').trim();

// ---- Safety checks ----
const W = deck.pageSize.width.magnitude;
const H = deck.pageSize.height.magnitude;
if (!(H > W)) throw new Error('Template is not portrait. Check Page setup in the template.');
if (!deck.slides || deck.slides.length !== 1) throw new Error('Expected the copied template to have exactly 1 slide.');
if (deck.slides[0].pageElements && deck.slides[0].pageElements.length) throw new Error('Cover slide in the template is not empty. Delete its boxes.');
const coverId = deck.slides[0].objectId;

// ---- Helpers ----
const PX = W / 1080;
const px = n => Math.round(n * PX);
const M = 90;
const rgb = h => ({
  red: parseInt(h.slice(1, 3), 16) / 255,
  green: parseInt(h.slice(3, 5), 16) / 255,
  blue: parseInt(h.slice(5, 7), 16) / 255
});
const lum = h => {
  const c = [1, 3, 5].map(i => {
    const v = parseInt(h.slice(i, i + 2), 16) / 255;
    return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
  });
  return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
};
const contrast = (a, b) => {
  const x = lum(a), y = lum(b);
  return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05);
};
const readableOn = (bg, preferred) =>
  contrast(preferred, bg) >= 4.5 ? preferred : (lum(bg) > 0.5 ? '#1A1A1A' : '#FFFFFF');

// ---- Theme ----
const t = d.theme;
const bgColor = t.background;
const accent = t.accent;
const textColor = readableOn(bgColor, t.text);
const onAccent = readableOn(accent, textColor);
const ctaOnAccent = contrast(textColor, accent) >= 4.5;
const ctaBg = ctaOnAccent ? accent : bgColor;
const ctaBar = ctaOnAccent ? textColor : accent;
const ctaText = readableOn(ctaBg, textColor);
const buttonText = readableOn(ctaBar, ctaBg);

const reqs = [];

const setBg = (pageId, hex) => reqs.push({
  updatePageProperties: {
    objectId: pageId,
    pageProperties: { pageBackgroundFill: { solidFill: { color: { rgbColor: rgb(hex) } } } },
    fields: 'pageBackgroundFill.solidFill.color'
  }
});

const create = (id, pageId, shapeType, x, y, w, h) => reqs.push({
  createShape: {
    objectId: id,
    shapeType,
    elementProperties: {
      pageObjectId: pageId,
      size: { width: { magnitude: px(w), unit: 'EMU' }, height: { magnitude: px(h), unit: 'EMU' } },
      transform: { scaleX: 1, scaleY: 1, translateX: px(x), translateY: px(y), unit: 'EMU' }
    }
  }
});

const fillShape = (id, pageId, type, x, y, w, h, hex) => {
  create(id, pageId, type, x, y, w, h);
  reqs.push({
    updateShapeProperties: {
      objectId: id,
      shapeProperties: {
        shapeBackgroundFill: { solidFill: { color: { rgbColor: rgb(hex) } } },
        outline: { propertyState: 'NOT_RENDERED' }
      },
      fields: 'shapeBackgroundFill.solidFill.color,outline.propertyState'
    }
  });
};

const styleText = (id, font, size, bold, hex, align, lineSpacing) => {
  reqs.push({
    updateTextStyle: {
      objectId: id,
      textRange: { type: 'ALL' },
      style: {
        fontFamily: font,
        fontSize: { magnitude: size, unit: 'PT' },
        bold,
        foregroundColor: { opaqueColor: { rgbColor: rgb(hex) } }
      },
      fields: 'fontFamily,fontSize,bold,foregroundColor'
    }
  });
  reqs.push({
    updateParagraphStyle: {
      objectId: id,
      textRange: { type: 'ALL' },
      style: { alignment: align, lineSpacing },
      fields: 'alignment,lineSpacing'
    }
  });
};

const anchorText = (id, anchor) => reqs.push({
  updateShapeProperties: {
    objectId: id,
    shapeProperties: { contentAlignment: anchor },
    fields: 'contentAlignment'
  }
});

const text = (id, pageId, x, y, w, h, str, font, size, bold, hex, anchor) => {
  if (!str) return;
  create(id, pageId, 'TEXT_BOX', x, y, w, h);
  reqs.push({ insertText: { objectId: id, insertionIndex: 0, text: String(str) } });
  styleText(id, font, size, bold, hex, 'START', 112);
  if (anchor) anchorText(id, anchor);
};

const badge = (id, pageId, x, y, size, label, font, hex, textHex) => {
  fillShape(id, pageId, 'ELLIPSE', x, y, size, size, hex);
  reqs.push({ insertText: { objectId: id, insertionIndex: 0, text: String(label) } });
  styleText(id, font, 34, true, textHex, 'CENTER', 100);
  anchorText(id, 'MIDDLE');
};

const button = (id, pageId, x, y, w, h, label, font, fillHex, textHex) => {
  fillShape(id, pageId, 'ROUND_RECTANGLE', x, y, w, h, fillHex);
  reqs.push({ insertText: { objectId: id, insertionIndex: 0, text: String(label) } });
  styleText(id, font, 28, true, textHex, 'CENTER', 100);
  anchorText(id, 'MIDDLE');
};

const bodySize = (s, isCta) => {
  const n = (s || '').length;
  if (isCta) return n <= 140 ? 36 : 32;
  return n <= 150 ? 42 : n <= 210 ? 38 : 32;
};

const total = d.slides.length + 1;

// 1) Create new slides (cover already exists as `coverId`)
d.slides.forEach((s, i) => {
  reqs.push({
    createSlide: {
      objectId: `slide_${i + 1}`,
      insertionIndex: i + 1,
      slideLayoutReference: { predefinedLayout: 'BLANK' }
    }
  });
});

// 2) Cover
setBg(coverId, bgColor);
fillShape('cover_circle', coverId, 'ELLIPSE', 640, -230, 640, 640, accent);
fillShape('cover_bar', coverId, 'RECTANGLE', M, 560, 160, 16, accent);
text('cover_title', coverId, M, 610, 1080 - 2 * M, 520, d.coverTitle, t.headingFont, 80, true, textColor);
text('cover_footer', coverId, M, 1190, 1080 - 2 * M, 70, brand || 'Swipe \u2192', t.bodyFont, 24, false, textColor);

// 3) Content + CTA slides
d.slides.forEach((s, i) => {
  const pageId = `slide_${i + 1}`;
  const isCta = i === d.slides.length - 1;
  const fg = isCta ? ctaText : textColor;
  setBg(pageId, isCta ? ctaBg : bgColor);

  if (!isCta) {
    badge(`badge_${i + 1}`, pageId, M, 130, 120, i + 1, t.headingFont, accent, onAccent);
    text(`title_${i + 1}`, pageId, M, 280, 1080 - 2 * M, 420, s.heading, t.headingFont, 62, true, fg, 'BOTTOM');
    fillShape(`bar_${i + 1}`, pageId, 'RECTANGLE', M, 730, 160, 16, accent);
    text(`body_${i + 1}`, pageId, M, 790, 1080 - 2 * M, 400, s.body, t.bodyFont, bodySize(s.body, false), false, fg);
  } else {
    // CTA slide: tighter layout so the button fits below the body
    text(`title_${i + 1}`, pageId, M, 200, 1080 - 2 * M, 420, s.heading, t.headingFont, 62, true, fg, 'BOTTOM');
    fillShape(`bar_${i + 1}`, pageId, 'RECTANGLE', M, 650, 160, 16, ctaBar);
    text(`body_${i + 1}`, pageId, M, 710, 1080 - 2 * M, 280, s.body, t.bodyFont, bodySize(s.body, true), false, fg);
    if (brand) {
      button(`cta_button`, pageId, M, 1040, 1080 - 2 * M, 130, brand, t.headingFont, ctaBar, buttonText);
    }
  }
});

return [{
  json: {
    presentationId,
    slideCount: total,
    requestCount: reqs.length,
    requests: reqs
  }
}];

const id = $('Build Requests').first().json.presentationId;
const d = $('Parse').first().json;

return [{
  json: {
    editLink: `https://docs.google.com/presentation/d/${id}/edit`,
    pdfDownload: `https://docs.google.com/presentation/d/${id}/export/pdf`,
    platform: d.platform,
    caption: d.caption,
    hashtags: d.hashtags,
    headlineOptions: d.headlineOptions
  }
}];
